WITH rollup_totals AS (SELECT d.dept_name, src.level, COUNT(*) AS cnt, SUM(src.salary) AS total_salary, GROUPING_ID() AS gid FROM employees src LEFT JOIN departments d ON src.dept_id = d.id GROUP BY ROLLUP (d.dept_name, src.level)) SELECT level, total_salary, gid, CASE WHEN level RLIKE '^(L1|L2)$' THEN 'GROUP_B' ELSE 'OTHER_ZONE' END AS level_zone FROM rollup_totals ORDER BY gid DESC NULLS LAST
